"""Read the equipment desk snapshot. Command: python3 src/ledger.py."""

import json
from pathlib import Path


def load_snapshot():
    path = Path(__file__).resolve().parents[1] / "data" / "equipment.json"
    return json.loads(path.read_text())


def loan_lines(snapshot):
    names = {person["id"]: person["name"] for person in snapshot["borrowers"]}
    return [
        f'{item["tag"]} | {item["name"]} | '
        f'{names[item["borrower_id"]]} ({item["borrower_id"]}) | {item["due"]}'
        for item in snapshot["equipment"]
        if item["state"] == "on_loan"
    ]


if __name__ == "__main__":
    print("\n".join(loan_lines(load_snapshot())))
